#!/usr/bin/env bash
# 배포 직전 Antigravity 네 관점 검토(고치지 않고 글만). 이 작업 폴더의 루트에서 실행.
cd "$(dirname "$0")/.." || exit 1
COMMON='Read-only review. Do not modify, create or delete any file except your own output. No git commands that change anything. No next build. Run every command in the foreground. Project: VOILA, a mystery box shop (Next.js app under web/). Read DESIGN.md first (design canon: one white pill primary button per screen, at most two underlined links, no colors, badges or shadows, blocked states inline). The change under review is the range 4c8942f..HEAD on this branch (run: git diff 4c8942f..HEAD --stat, then read the changed files). It adds: an upgrade flow (stake a held item for a pricier one; web/components/flow/UpgradeSheet.tsx, entries in Opening.tsx, Reveal.tsx, InventoryScreen.tsx, app/upgrade.css), a new order of the all-boxes grid (web/lib/boxOrder.ts, BoxList.tsx), browser storage compaction (no visible change), and the review section restored to the original horizontal card row (BoxReviews.tsx, ReviewsScreen.tsx, ui.css). A dev server runs at http://localhost:3003 (Playwright is in web/node_modules; everything is a fake test ledger; do not submit withdrawal or shipping forms). Screenshots to look at: qa/work/upgrade/*.png, qa/work/order-r/*.png, qa/work/reviews-v7/before and after. Answer in Korean, plain text, no em dash characters, no middle dot characters, no exclamation marks. Give concrete evidence: file and line, screenshot file, or measured value. End with a ranked list of proposed changes, each with the expected effect and the regression risk; separate what blocks deployment from what can wait.'
run() {
  rtk agy --dangerously-skip-permissions --model gemini-3.8-flash-high --effort high --print "$COMMON Your focus: $2" > "flow/agy-restore-$1.txt" 2>&1
  echo "done $1 exit $?"
}
run 1 "visual hierarchy and design consistency against DESIGN.md: the upgrade sheet (pick, draw, success, failure), the result screen with the new quiet upgrade button, the inventory item detail, the home grid order, the review card row; count primary buttons and underlined links per screen." &
run 2 "responsive behaviour and accessibility: widths 320, 390, 768, 1440 in ko, en and zh for the upgrade sheet and the review row; text overflow in the new copy; touch targets; keyboard operation of the upgrade sheet (tab order, enter, escape, focus return); screen-reader semantics of the draw bar and the result; reduced motion." &
run 3 "interaction states, data handling and robustness in the browser: drive the upgrade on 3003 with a seeded state (see web/scripts/capture/states.mjs and flow-upgrade.mjs), double press, press during the draw, refresh mid-draw, back navigation, two tabs; the review row appending 20 at a time while scrolling and back navigation restoring the row; the home grid order after opening a box and returning; the storage compaction after many openings (no console errors, inventory intact after reload)." &
run 4 "component architecture and maintainability of the new code: UpgradeSheet.tsx, upgrade*.ts, boxOrder.ts, compactStorage.ts, the restored BoxReviews.tsx; duplication with existing take and opening code, hooks correctness, cleanup, test coverage in web/tests, and refactoring opportunities that do not change behaviour." &
wait
